","print_orientation":"Flat closed back on bed at z=0; nut pocket upward. No supports.","use_orientation":"Bolt passes through closed back, through captive nut, and out open face."},{"id":"fit_coupon","role":"coupon","material":"PLA","code":"import math

def build(p):
    e=p.boolean_extra
    def pts(af):
        r=af/math.sqrt(3)
        return [(r*math.cos(math.radians(30+60*i)),r*math.sin(math.radians(30+60*i))) for i in range(6)]
    def socket(interference):
        b=cq.Workplane('XY').circle(p.knob_d/2).extrude(p.knob_h)
        for i in range(p.flute_count):
            a=2*math.pi*i/p.flute_count
            b=b.cut(cq.Workplane('XY').center(p.flute_center_r*math.cos(a),p.flute_center_r*math.sin(a)).circle(p.flute_r).extrude(p.knob_h+e))
        b=b.cut(cq.Workplane('XY').workplane(offset=p.floor_h).polyline(pts(p.nut_af+p.pocket_clearance)).close().extrude(p.knob_h-p.floor_h+e))
        rc=p.nut_af/2-interference/2+p.rib_r
        for i in range(6):
            a=math.radians(60*i)
            b=b.union(cq.Workplane('XY').workplane(offset=p.floor_h-e).center(rc*math.cos(a),rc*math.sin(a)).circle(p.rib_r).extrude(p.knob_h-p.floor_h+e))
        entry=cq.Workplane('XY').workplane(offset=p.knob_h-p.entry_h).polyline(pts(p.nut_af-interference)).close().workplane(offset=p.entry_h).polyline(pts(p.nut_af+p.pocket_clearance+p.entry_extra_af)).close().loft(combine=True)
        b=b.cut(entry)
        return b.cut(cq.Workplane('XY').workplane(offset=-e).circle((p.bolt_d+p.bolt_clearance)/2).extrude(p.knob_h+2*e))
    result=cq.Workplane('XY').box(2*p.coupon_spacing,p.coupon_link_w,p.floor_h,centered=(True,True,False))
    for j in range(3):
        x=(j-1)*p.coupon_spacing
        result=result.union(socket(p.nut_interference+(j-1)*p.coupon_step).translate((x,0,0)))
        for k in range(j+1):
            dx=(k-j/2)*p.coupon_dot_spacing
            result=result.union(cq.Workplane('XY').workplane(offset=p.knob_h).center(x+dx,p.coupon_dot_y).circle(p.coupon_dot_r).extrude(p.coupon_dot_h))
    return result
